import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the optimized CUDA kernel for matrix multiplication using shared memory
matmul_shared_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void matmul_shared_kernel(const float* A, const float* B, float* C, int N) {
    __shared__ float sA[16][16];
    __shared__ float sB[16][16];

    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    float sum = 0.0f;

    for (int tile = 0; tile < N / 16; ++tile) {
        // Load tiles of A and B into shared memory
        sA[threadIdx.y][threadIdx.x] = A[row * N + (tile * 16 + threadIdx.x)];
        sB[threadIdx.y][threadIdx.x] = B[(tile * 16 + threadIdx.y) * N + col];
        __syncthreads();

        // Compute the dot product for the current tile
        for (int k = 0; k < 16; ++k) {
            sum += sA[threadIdx.y][k] * sB[k][threadIdx.x];
        }
        __syncthreads();
    }

    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

torch::Tensor matmul_shared_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros_like(A);

    dim3 block_size(16, 16);
    dim3 grid_size((N + block_size.x - 1) / block_size.x, (N + block_size.y - 1) / block_size.y);

    matmul_shared_kernel<<<grid_size, block_size>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
"""

matmul_shared_cpp_source = "torch::Tensor matmul_shared_cuda(torch::Tensor A, torch::Tensor B);"

# Compile the inline CUDA code for matrix multiplication with shared memory
matmul_shared = load_inline(
    name="matmul_shared",
    cpp_sources=matmul_shared_cpp_source,
    cuda_sources=matmul_shared_source,
    functions=["matmul_shared_cuda"],
    verbose=True,
    extra_cflags=[""],
    extra_ldflags=[""],
)

class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.matmul_shared = matmul_shared

    def forward(self, A, B):
        return self.matmul_shared.matmul_shared_cuda(A, B)"}

